import type { PartyKey, Source } from './research';

export type DossierAttribution = PartyKey | 'cross';
export type DossierKind = 'Law' | 'Policy architecture' | 'Treaty' | 'Trade agreement' | 'Defence pact' | 'Tax protocol' | 'Court-tested scheme';

export type DossierPoint = { title:string; detail:string };
export type UnderReadPoint = { label:string; detail:string; whyItMatters:string };

export type Dossier = {
  id:string;
  slug:string;
  attribution:DossierAttribution;
  government:string;
  year:number;
  date:string;
  kind:DossierKind;
  sector:string;
  countries:string[];
  title:string;
  deck:string;
  status:string;
  overview:string;
  provisions:DossierPoint[];
  benefits:string[];
  tradeoffs:string[];
  underRead:UnderReadPoint[];
  implementation:string;
  evidenceNote:string;
  sourceIds:string[];
};

